function Base() {
  this.kind = new.target.name;
}

class Gift {}

const made = Reflect.construct(Base, [], Gift);
console.log(made.kind, made instanceof Gift, made instanceof Base);

const shelf = { count: 1 };
const other = {};

console.log(Reflect.set(shelf, "count", 9, other));
console.log(shelf.count, other.count);
